export function rollMysteryPet(fixedRoll?: number): StudentPet {
  const roll = fixedRoll !== undefined ? fixedRoll : Math.random() * 100;

  if (roll < 50) {
    // 50% Common (3 stages)
    const candidates = [createSproutlingPet, createPipflickPet, createEmbersqueakPet, createZephyrpuffPet];
    const pick = candidates[Math.floor(Math.random() * candidates.length)];
    return pick(1, false);
  }

  if (roll < 78) {
    // 28% Rare (4 stages)
    const candidates = [createFrostpawPet, createMagmafangPet, createVoltwingPet, createThundercatPet];
    const pick = candidates[Math.floor(Math.random() * candidates.length)];
    return pick(1, false);
  }

  if (roll < 92) {
    // 14% Epic (5 stages)
    const candidates = [createFirePhoenixPet, createChronoChimeraPet, createShadowpantherPet, createStormstagPet];
    const pick = candidates[Math.floor(Math.random() * candidates.length)];
    return pick(1, false);
  }

  if (roll < 98) {
    // 6% Legendary (6 stages)
    const candidates = [createAstralDragonPet, createAstralLeviathanPet, createSolarWyvernPet];
    const pick = candidates[Math.floor(Math.random() * candidates.length)];
    return pick(1, false);
  }

  // 2% Mythic (8 stages)
  const candidates = [createVoidDragonPet, createChronoDracoPet, createAegisPaladinPet];
  const pick = candidates[Math.floor(Math.random() * candidates.length)];
  return pick(1, false);
}

